1	export type Card = {
2	  monster: string;
3	  rank?: number;
4	};
5	
6	const SCORE_WITHOUT_SPHINX = 0;
7	const SPHINX_POINT = 1;
8	const POINT_FOR_THREE_OTHER_TYPES_OR_FEWER = 1;
9	const OTHER_TYPE_THRESHOLD = 3;
10	const POINTS_PER_OTHER_TYPE_BEYOND_THRESHOLD = 2;
11	/** The Sphinx scores the *company* it keeps, so its own type is not counted. */
12	const SPHINX_OWN_TYPE = 1;
13	
14	const countSphinxes = (army: Card[]): number =>
15	  army.filter((card) => card.monster === "sphinx").length;
16	
17	const countTypes = (army: Card[]): number =>
18	  new Set(army.map((card) => card.monster)).size;
19	
20	const countOtherTypes = (army: Card[]): number =>
21	  countTypes(army) - SPHINX_OWN_TYPE;
22	
23	const countOtherTypesBeyondThreshold = (army: Card[]): number =>
24	  Math.max(countOtherTypes(army) - OTHER_TYPE_THRESHOLD, 0);
25	
26	const scoreTypes = (army: Card[]): number => {
27	  const otherTypesBeyondThreshold = countOtherTypesBeyondThreshold(army);
28	  if (otherTypesBeyondThreshold === 0)
29	    return POINT_FOR_THREE_OTHER_TYPES_OR_FEWER;
30	  return POINTS_PER_OTHER_TYPE_BEYOND_THRESHOLD * otherTypesBeyondThreshold;
31	};
32	
33	export const scoreArmy = (army: Card[]): number => {
34	  const sphinxes = countSphinxes(army);
35	  if (sphinxes === 0) return SCORE_WITHOUT_SPHINX;
36	  return sphinxes * (SPHINX_POINT + scoreTypes(army));
37	};
